PRAGMA foreign_keys = ON;
PRAGMA foreign_key_check;

-- Gold Query
SELECT T2.name FROM foreign_data AS T1 INNER JOIN cards AS T2 ON T2.uuid = T1.uuid INNER JOIN sets AS T3 ON T3.code = T2.setCode WHERE T3.name = 'Coldsnap' AND T1.language = 'Italian' ORDER BY T2.convertedManaCost DESC, T1.id NULLS LAST, T2.id NULLS LAST, T3.id NULLS LAST LIMIT 1;

/*
Gold Result:
('default1',)
*/

-- Prediction Query
SELECT T2.name FROM sets AS T1 INNER JOIN cards AS T3 ON T1.code = T3.setCode INNER JOIN foreign_data AS T2 ON T3.uuid = T2.uuid WHERE T1.name = 'Coldsnap' AND T2.language = 'Italian' ORDER BY T3.convertedManaCost DESC, T1.id NULLS LAST, T3.id NULLS LAST, T2.id NULLS LAST LIMIT 1;

